/**
 * registryMeta — loads the build-time registry validation report + import
 * metadata manifest (generated by scripts/validate_registry.py) so the UI
 * can display data provenance and quality without parsing the raw CSV.
 *
 * Both files are tiny JSON fetched next to the runtime database
 * (/downloads/...), cached by the service worker like other downloads.
 */

export interface RegistryValidationReport {
  schemaVersion: number;
  generatedAt: string;
  source: {
    file: string;
    sha256: string;
    sizeBytes: number;
    headers: string[];
  };
  counts: Record<string, number>;
  notes: string[];
}

export interface RegistryImportMeta {
  schemaVersion: number;
  generatedAt: string;
  source: RegistryValidationReport['source'];
  runtimeDatabase?: {
    file: string;
    sha256: string;
    sizeBytes: number;
    productCount?: number;
    missingMoa?: number;
    emptyCrops?: number;
    emptyPests?: number;
  } | null;
  validationCounts: Record<string, number>;
}

let cachedReport: RegistryValidationReport | null = null;
let cachedMeta: RegistryImportMeta | null = null;

async function fetchJson<T>(path: string): Promise<T | null> {
  try {
    const res = await fetch(path, { headers: { Accept: 'application/json' } });
    if (!res.ok) return null;
    return (await res.json()) as T;
  } catch {
    return null; // offline-first: provenance display is optional data
  }
}

export async function loadRegistryValidationReport(): Promise<RegistryValidationReport | null> {
  if (cachedReport) return cachedReport;
  cachedReport = await fetchJson<RegistryValidationReport>('/downloads/registry_validation_report.json');
  return cachedReport;
}

export async function loadRegistryImportMeta(): Promise<RegistryImportMeta | null> {
  if (cachedMeta) return cachedMeta;
  cachedMeta = await fetchJson<RegistryImportMeta>('/downloads/registry_import_meta.json');
  return cachedMeta;
}
